/* --- Prestadores primarios (ítem 11, RN-011) ----------------------------
   5 prestadores de la red pública de Cali. Los códigos
   llevan prefijo PROV- a propósito: el REPS usa otro formato y no deben
   confundirse con códigos de habilitación reales.                          */
ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre, vigente = true;

/* --- Territorios y microterritorios (RN-007, RN-008, Anexo A) -----------
   110 territorios: 30 rurales, 80 urbanos.
   El instrumento no asigna nombre propio al territorio: su código lo identifica. */
ON CONFLICT (codigo) DO UPDATE
  SET es_rural = EXCLUDED.es_rural, uzpe_codigo = EXCLUDED.uzpe_codigo;

ON CONFLICT (territorio_codigo, codigo) DO UPDATE
  SET nombre = EXCLUDED.nombre, comuna = EXCLUDED.comuna;

/* --- Dominios de listas cerradas ---------------------------------------- */
ON CONFLICT (codigo) DO UPDATE SET multiple = EXCLUDED.multiple, regla = EXCLUDED.regla;

/* --- Opciones ----------------------------------------------------------- */
